void selectiveBackupRackTests(){
    using M=Metropolix;using namespace metrobackup;
    rack::plugin::Plugin plugin;plugin.slug="MetropolixLab";modelMetropolix->plugin=&plugin;modelMetropolix->slug="Metropolix";plugin.models.push_back(modelMetropolix);rack::plugin::plugins.push_back(&plugin);
    auto source=std::unique_ptr<M>(new M),destination=std::unique_ptr<M>(new M);source->model=destination->model=modelMetropolix;source->id=824;destination->id=825;
    source->params[M::stageParam(0,0,M::CV)].setValue(-2.75f);source->params[M::modParam(0,M::MOD_VALUE)].setValue(-3.25f);
    for(int n=0;n<64;++n)if(n%3==0 || n==63){auto preset=source->capturePreset();preset.values[M::PITCH]=n/63.f;source->putPreset(n,preset);}
    destination->params[M::TEMPO].setValue(179.25f);destination->params[M::LOAD_PITCH].setValue(M::PitchThru);destination->params[M::PITCH].setValue(.2f);destination->panelPickup[0].recall(.2f,.8f);
    destination->params[M::RUN_ON_BOOT].setValue(1);destination->params[M::RUN].setValue(1);destination->expanded.store(true);destination->modEditor.store(true);destination->backupPresetCursor.store(9);
    for(int n=0;n<64;++n){auto preset=destination->capturePreset();preset.values[M::PITCH]=.55f;destination->putPreset(n,preset);}
    M::ChainState chains;metro::ChainLink link;link.slot=63;link.repeats=3;link.mutes=5;chains.working.insert(0,link);chains.saved[2]=chains.working;chains.loaded=2;destination->setChainState(chains);
    Json module(APP->engine->moduleToJson(source.get())),original(APP->engine->moduleToJson(destination.get()));std::string error;Scope scope=All;
    auto verifyImport=[&](json_t* backup,int selectedBank){
        APP->engine->moduleFromJson(destination.get(),original.get());Json before,after;
        require(restore(destination.get(),backup,before,after,error),"selective preset restore succeeds");
        Json actual(APP->engine->moduleToJson(destination.get()));auto* data=json_object_get(actual.get(),"data");auto* old=json_object_get(original.get(),"data");
        for(int n=0;n<64;++n){bool touched=selectedBank<0?source->getPreset(n).occupied:n/8==selectedBank;
            auto* expected=json_array_get(json_object_get(touched?json_object_get(module.get(),"data"):old,"presets"),n);
            require(json_equal(json_array_get(json_object_get(data,"presets"),n),expected),"only explicitly selected absolute slots change, including bank empties");
        }
        for(const char* key:{"chains","chainFormat","midiInput","midiOutput","pickup","expanded","modEditor","backupPresetCursor"})require(json_equal(json_object_get(data,key),json_object_get(old,key)),"selective import preserves chains, local devices, pickup and panel state");
        auto* currentParams=json_object_get(actual.get(),"params");auto* originalParams=json_object_get(original.get(),"params");
        for(int n=0;n<M::NUM_PARAMS;++n)if(n!=M::RUN && n!=M::RESET)require(json_equal(json_array_get(currentParams,n),json_array_get(originalParams,n)),"selective import preserves all non-transport live settings");
        require(destination->id==825 && destination->integer(M::RUN)==0 && destination->integer(M::RESET)==0,"selective import preserves identity and stops transport");
        APP->engine->moduleFromJson(destination.get(),before.get());Json undone(APP->engine->moduleToJson(destination.get()));require(json_equal(undone.get(),original.get()),"selective history receipt restores exact original module");
        APP->engine->moduleFromJson(destination.get(),after.get());Json redone(APP->engine->moduleToJson(destination.get()));require(json_equal(redone.get(),actual.get()),"selective redo restores exact stopped imported module");
    };
    for(int bank=0;bank<8;++bank){Json selected(captureSelected(module.get(),bank));require(validate(destination.get(),selected.get(),scope,error) && scope==Presets,"each of eight banks validates");auto* slots=json_object_get(json_object_get(selected.get(),"bank"),"slots");require(json_array_size(slots)==8,"bank exports exactly eight entries");for(int n=0;n<8;++n)require(json_integer_value(json_object_get(json_array_get(slots,n),"slot"))==bank*8+n,"bank entries use absolute slot IDs");verifyImport(selected.get(),bank);}
    Json filled(captureSelected(module.get(),-1));require(validate(destination.get(),filled.get(),scope,error),"sparse filled backup validates");auto* slots=json_object_get(json_object_get(filled.get(),"bank"),"slots");require(json_array_size(slots)==22,"filled exports only occupied presets across all banks");verifyImport(filled.get(),-1);
    source->putPreset(0,M::Snapshot{});for(int n=0;n<64;++n)source->putPreset(n,M::Snapshot{});Json emptyModule(APP->engine->moduleToJson(source.get())),empty(captureSelected(emptyModule.get(),-1));require(validate(destination.get(),empty.get(),scope,error) && json_array_size(json_object_get(json_object_get(empty.get(),"bank"),"slots"))==0,"empty filled export is valid");verifyImport(empty.get(),-1);
    auto rejects=[&](Json bad,const char* message){Json before(APP->engine->moduleToJson(destination.get())),old,next;require(!restore(destination.get(),bad.get(),old,next,error) && !error.empty(),message);Json after(APP->engine->moduleToJson(destination.get()));require(json_equal(before.get(),after.get()),"rejected selective document cannot mutate the module");};
    auto copy=[&](){return Json(json_deep_copy(filled.get()));};
    {auto bad=copy();json_array_append(json_object_get(json_object_get(bad.get(),"bank"),"slots"),json_array_get(slots,0));rejects(std::move(bad),"duplicate selective slot rejects");}
    {auto bad=copy();json_object_set_new(json_array_get(json_object_get(json_object_get(bad.get(),"bank"),"slots"),0),"values",json_null());rejects(std::move(bad),"filled document cannot erase a preset");}
    {auto bad=copy();json_object_set_new(bad.get(),"scope",json_string("all"));rejects(std::move(bad),"selective all scope rejects");}
    {auto bad=copy();json_object_set_new(bad.get(),"state",json_object());rejects(std::move(bad),"selective document cannot import settings");}
    {auto bad=copy();json_object_set_new(json_object_get(bad.get(),"selection"),"kind",json_string("unknown"));rejects(std::move(bad),"unknown selection rejects");}
    {auto bad=copy();json_object_set_new(json_object_get(bad.get(),"selection"),"bank",json_integer(1));rejects(std::move(bad),"filled selection cannot contain a bank number");}
    {auto bad=copy();json_object_set_new(json_object_get(bad.get(),"bank"),"presetFormat",json_integer(8));rejects(std::move(bad),"older selective snapshot sizes reject");}
    {auto bad=copy();json_array_remove(json_object_get(json_array_get(json_object_get(json_object_get(bad.get(),"bank"),"slots"),0),"values"),517);rejects(std::move(bad),"truncated selective snapshot rejects");}
    {auto bad=copy();json_object_set_new(json_array_get(json_object_get(json_object_get(bad.get(),"bank"),"slots"),0),"slot",json_integer(4294967296LL));rejects(std::move(bad),"64-bit slot cannot wrap to a valid ID");}
    {auto bad=copy();json_object_del(json_array_get(json_object_get(json_object_get(bad.get(),"bank"),"slots"),0),"values");rejects(std::move(bad),"missing snapshot values reject");}
    for(int n=0;n<M::SNAPSHOT_PARAMS;++n){auto bad=copy();json_array_set_new(json_object_get(json_array_get(json_object_get(json_object_get(bad.get(),"bank"),"slots"),0),"values"),n,json_real(destination->paramQuantities[M::presetParam(n)]->maxValue+100.));rejects(std::move(bad),"every selective snapshot field enforces its parameter range");}
    for(int test=0;test<4;++test){Json bad(captureSelected(module.get(),7));auto* bankSlots=json_object_get(json_object_get(bad.get(),"bank"),"slots");if(test==0)json_array_remove(bankSlots,0);if(test==1)json_object_set_new(json_array_get(bankSlots,0),"slot",json_integer(0));if(test==2)json_object_set_new(json_object_get(bad.get(),"selection"),"bank",json_integer(9));if(test==3)json_object_del(bad.get(),"selection");rejects(std::move(bad),"incomplete or foreign bank selection rejects");}
    for(int kind=0;kind<2;++kind)for(int schema=29;schema<=30;++schema){Json legacy(capture(module.get(),static_cast<Scope>(kind)));json_object_set_new(legacy.get(),"params",json_deep_copy(json_object_get(legacy.get(),"params")));auto* parameters=json_object_get(legacy.get(),"params");while(json_array_size(parameters)>M::FORMAT31_NUM_PARAMS)json_array_remove(parameters,json_array_size(parameters)-1);auto* state=json_object_get(legacy.get(),"state");json_object_set_new(state,"schemaVersion",json_integer(schema));json_object_del(state,"setupDirectChild");json_object_del(state,"factoryCursor");if(schema<30)json_object_del(state,"backupPresetCursor");require(validate(destination.get(),legacy.get(),scope,error),"2.26 through 2.29 full/settings backups remain valid");destination->backupPresetCursor.store(9);destination->factoryCursor.store(1);Json before,after;require(restore(destination.get(),legacy.get(),before,after,error) && destination->factoryCursor.load()==0 && (schema==30 || destination->backupPresetCursor.load()==0),"legacy backup defaults newly added cursors instead of retaining stale state");}
    const std::string path="build/tests/selective-é-音.json";require(write(path,filled.get(),error),"selective backup writes a Unicode path");Json loaded(read(path,error));require(loaded && validate(destination.get(),loaded.get(),scope,error),"written selective file validates");auto* loadedSlots=json_object_get(json_object_get(loaded.get(),"bank"),"slots");require(json_array_size(loadedSlots)==json_array_size(slots),"selective file preserves slot count");for(size_t i=0;i<json_array_size(slots);++i){require(json_equal(json_object_get(json_array_get(slots,i),"slot"),json_object_get(json_array_get(loadedSlots,i),"slot")),"file preserves absolute slot IDs");for(int n=0;n<M::SNAPSHOT_PARAMS;++n)require(float(json_number_value(json_array_get(json_object_get(json_array_get(slots,i),"values"),n)))==float(json_number_value(json_array_get(json_object_get(json_array_get(loadedSlots,i),"values"),n))),"signed and dormant snapshot values roundtrip exactly as float32");}discard(path);
    Json example(captureSelected(module.get(),7));require(write("build/tests/Selective-bank-8.json",example.get(),error),"selective example exported by native module");
    // Selective imports use the same external-Run inhibit as full backups.
    destination->params[M::RESET_INPUT_MODE].setValue(1);destination->params[M::RUN].setValue(1);destination->inputs[M::RESET_IN].channels=1;destination->inputs[M::RESET_IN].setVoltage(5);Module::ProcessArgs args{};args.sampleRate=48000;args.sampleTime=1.f/48000;
    for(int n=0;n<64;++n)destination->process(args);Json before,after;require(restore(destination.get(),filled.get(),before,after,error),"selective import under held Run gate succeeds");for(int n=0;n<64;++n)destination->process(args);require(!destination->sequencer.running && destination->outputs[M::GATE_1].getVoltage()==0,"selective import cannot restart under already held external Run");destination->inputs[M::RESET_IN].setVoltage(0);for(int n=0;n<64;++n)destination->process(args);destination->inputs[M::RESET_IN].setVoltage(5);for(int n=0;n<64;++n)destination->process(args);require(destination->sequencer.running,"new external Run edge resumes after selective import");
    rack::plugin::plugins.pop_back();plugin.models.clear();modelMetropolix->plugin=nullptr;
    std::cout<<"PASS: selective Filled/8-bank backups, exact receipts, old schemas, invalid files and transport inhibit\n";
}
